const b = $input.item.json.body || $input.item.json;
const description = String(b.description || '').trim().substring(0, 3000);
const email = String(b.email || '').trim().toLowerCase();
if (!description) throw new Error('description requise');
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) throw new Error('email invalide');
const photos = (Array.isArray(b.photos) ? b.photos : [])
  .filter(u => /^https?:\/\//.test(String(u))).slice(0, 5).map(u => String(u).substring(0, 500));
return {
  nom: String(b.nom || '').substring(0, 255),
  prenom: String(b.prenom || '').substring(0, 255),
  email,
  telephone: String(b.telephone || '').substring(0, 50),
  ville: String(b.ville || '').substring(0, 255),
  description, photos
};

