const content = $input.item.json.message.content;
let q;
try { q = JSON.parse(content.match(/\{[\s\S]*\}/)[0]); }
catch(e) { q = { type_travaux: 'autre', urgence: 'normale', fourchette_basse: null,
  fourchette_haute: null, duree_estimee_jours: null, questions_a_poser: [],
  priorite_commerciale: 'normale' }; }
const d = $('Valider la demande').item.json;
return {
  ...d,
  ...q,
  message: `[${q.type_travaux} – ${q.urgence}] ${d.description}` +
    (d.photos.length ? `\nPhotos : ${d.photos.join(' ')}` : '')
};

